class Solution {
public:
    string largestMerge(string word1, string word2) {
        int n = word1.size(), m = word2.size();
        int i = 0, j = 0;
        string result;
        result.reserve(n + m);
        while (i < n || j < m) {
            if (i < n && (j >= m || word1.compare(i, string::npos, word2, j) > 0)) {
                result.push_back(word1[i++]);
            } else {
                result.push_back(word2[j++]);
            }
        }
        return result;
    }
};
